            log = appendLog(log, {
              turn: prev.game.turn,
              title: 'Manual edit',
              detail: `${c.name} set to ${to} (was ${from})`,
              changes: changes.map((ch) => ({
                name: ch.name,
                mechanic: ch.mechanic,
                from: ch.from,
                to: ch.to,
                chapter: ch.chapter,
              })),
            });
          } else {
            log = appendLog(log, {
              turn: prev.game.turn,
              title: 'Manual edit',
              detail: `${c.name} set to ${to} (was ${from})`,
            });
