describe('useGameState — Saga chapter triggers from manual edits', () => {
  function sagaInput(overrides: Partial<AddCardInput> = {}): AddCardInput {
    return {
      card: card(),
      mechanic: 'saga',
      direction: 'increment',
      startingCount: 0,
      targetCount: 3,
      chapters: ['Chapter I effect', 'Chapter II effect', 'Chapter III effect'],
      autoAdjust: true,
      ...overrides,
    };
  }

  it('setCount records multiple newly-crossed chapter thresholds', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(sagaInput({ startingCount: 0 })));
    const card = result.current.state.cards[0]!;
    expect(card.triggeredChapters).toEqual([]);
    act(() => result.current.setCount(card.instanceId, 2));
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
    const logEntry = result.current.state.log.find((e) => e.title === 'Manual edit');
    expect(logEntry).toBeDefined();
    expect(logEntry!.changes).toEqual([
      expect.objectContaining({
        name: 'Test Card',
        mechanic: 'saga',
        from: 0,
        to: 2,
        chapter: { number: 1, text: 'Chapter I effect' },
      }),
      expect.objectContaining({
        name: 'Test Card',
        mechanic: 'saga',
        from: 0,
        to: 2,
        chapter: { number: 2, text: 'Chapter II effect' },
      }),
    ]);
  });

  it('adjustCount records a newly-crossed chapter threshold when stepping up', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(sagaInput({ startingCount: 0 })));
    const card = result.current.state.cards[0]!;
    act(() => result.current.adjustCount(card.instanceId, 1));
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1]);
    const logEntry = result.current.state.log.find((e) => e.title === 'Manual adjustment');
    expect(logEntry).toBeDefined();
    expect(logEntry!.changes).toEqual([
      expect.objectContaining({
        name: 'Test Card',
        mechanism: 'saga',
        from: 0,
        to: 1,
        chapter: { number: 1, text: 'Chapter I effect' },
      }),
    ]);
  });

  it('moving count down does not un-trigger an already-recorded chapter', () => {
    const { result } = renderHook(() => useGameState());
    act(() => result.current.addCard(sagaInput({ startingCount: 0 })));
    const card = result.current.state.cards[0]!;
    act(() => result.current.setCount(card.instanceId, 2));
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
    act(() => result.current.adjustCount(card.instanceId, -1));
    expect(result.current.state.cards[0]!.triggeredChapters).toEqual([1, 2]);
    expect(result.current.state.cards[0]!.count).toBe(1);
  });
});

