  /** Manual override — set a card's counters to an exact value. */
  const setCount = useCallback((instanceId: string, count: number) => {
    setTracker((prev) => {
      let log = prev.game.log;
      const cards = prev.game.cards.map((c) => {
        if (c.instanceId !== instanceId) return c;
        const from = c.count;
        const to = clampCount(count, c.direction, c.targetCount);
        if (to !== from) {
          const triggeredNow = newlyTriggeredChapters(
            c.chapters ?? [],
            from,
            to,
            c.triggeredChapters ?? [],
          );
          const changes = triggeredNow.map((chapter) => ({
            instanceId: c.instanceId,
            name: c.name,
            mechanic: c.mechanic,
            step: 'precombatMain' as const,
            from,
            to,
            hitTarget: chapter.number === (c.chapters?.length ?? 0),
            resolveNote: c.resolveNote,
            chapter,
          }));
          if (changes.length > 0) {
            log = appendLog(log, {
              turn: prev.game.turn,
              title: 'Manual edit',
              detail: `${c.name} set to ${to} (was ${from})`,
              changes: changes.map((ch) => ({
                name: ch.name,
                mechanic: ch.mechanic,
                from: ch.from,
                to: ch.to,
                chapter: ch.chapter,
              })),
            });
          } else {
            log = appendLog(log, {
              turn: prev.game.turn,
              title: 'Manual edit',
              detail: `${c.name} set to ${to} (was ${from})`,
            });
